<template><el-select :model-value="modelValue" @update:model-value="$emit('update:modelValue',$event)" :multiple="multiple" filterable remote :remote-method="search" @visible-change="v=>v&&search('')" :loading="loading" placeholder="输入账号或昵称搜索" style="min-width:230px;max-width:100%"><el-option v-if="!multiple" :value="0" label="未分配"/><el-option v-for="r in rows" :key="r.userId" :value="r.userId" :label="`${r.nickName} (${r.userName}) #${r.userId}`"/></el-select><el-button v-if="total>50" link :disabled="loading||page*50>=total" @click="more">更多候选 ({{rows.length}}/{{total}})</el-button></template>
<script setup>
import{ref,onBeforeUnmount,onDeactivated}from'vue';import{workflow}from'@/api/cms/workflow';const props=defineProps({modelValue:{type:[Array,Number],default:0},multiple:Boolean,purpose:{type:String,default:'inquiry'},kind:{type:String,default:''}});defineEmits(['update:modelValue']);const rows=ref([]),total=ref(0),loading=ref(false);let epoch=0,page=1,name='';async function fetch(append){const n=++epoch;loading.value=true;try{const r=await workflow('workflow/people','get',undefined,{purpose:props.purpose,kind:props.kind,name,pageNum:page,pageSize:50});if(n===epoch){rows.value=append?[...rows.value,...r.rows]:r.rows;total.value=r.total}}finally{if(n===epoch)loading.value=false}}function search(v){name=v;page=1;fetch(false)}function more(){page++;fetch(true)}function close(){++epoch;loading.value=false}onBeforeUnmount(close);onDeactivated(close)
</script>
